-- Recharj — seed 002: courses
-- Run after 001_sources.sql (courses.content references source ids).
-- Generated from contenu-cours-mvp.md via generate-courses-seed.mjs, review before executing.

insert into courses (id, slug, title, order_index, tags, free_tier_included, level, parent_course_id, required_tier, content) values
('b0000000-0000-0000-0000-000000000001', 'demarrer-conversation', $$Démarrer une conversation$$, 1, ARRAY['conversation', 'debuter']::text[], true, 1, null, 'free', $json${"hook":"Tu es à une soirée. Tu vois un petit groupe qui rigole près du buffet. Ton cerveau te souffle : \"Ils ont l'air occupés, n'y va pas.\" Ton corps se fige. Cette scène, presque tous les introvertis la connaissent. Ce que ton cerveau vient de te dire est scientifiquement prévisible. Une étude a montré qu'il se trompe à tous les coups.","diagnostic":{"kind":"slider","question":"À quel point te sens-tu à l'aise pour aborder une personne que tu ne connais pas ?","min":1,"max":10,"minLabel":"Terrifié","maxLabel":"Aucun souci"},"cards":[{"title":"L'écart de sympathie","advice":"La personne en face de toi a presque toujours mieux vécu l'échange que ce que tu imagines après coup.","sourceId":"a0000000-0000-0000-0000-000000000001"},{"title":"La méthode FORD","advice":"Quand tu ne sais pas quoi dire, pense Famille, Occupation, loisirs (Récréation), Rêves : les 4 sujets qui ouvrent une conversation naturellement.","sourceId":"a0000000-0000-0000-0000-000000000002"},{"title":"Question ouverte, pas fermée","advice":"\"Qu'est-ce qui t'amène ici ce soir ?\" donne un vrai espace de réponse ; \"Tu t'amuses ?\" tue la conversation en un mot.","sourceId":"a0000000-0000-0000-0000-000000000003"},{"title":"Le commentaire de contexte","advice":"Le moyen le plus simple de démarrer : commenter ce qui vous entoure, ici et maintenant.","sourceId":"a0000000-0000-0000-0000-000000000002"},{"title":"Pose la question, puis tais-toi vraiment","advice":"Écoute réellement la réponse, ne prépare pas déjà ta prochaine phrase.","sourceId":"a0000000-0000-0000-0000-000000000004"},{"title":"Récap","advice":"Contexte ou FORD pour ouvrir, question ouverte pour laisser de la place, écart de sympathie pour te rassurer.","sourceId":null}],"exercise":{"kind":"predict-compare","prompt":"File d'attente pour un café, 10 secondes avant ton tour. Qu'est-ce que tu dirais ?","examples":["\"Ce café a l'air hyper populaire, tu viens souvent ?\" (commentaire de contexte)","\"Vous bossez dans le coin ?\" (FORD, occupation)","\"Qu'est-ce que vous recommandez ici ?\" (question ouverte)"]},"personalization":{"condition":"<=4","reorderCardIndexFirst":0}}$json$::jsonb),

('b0000000-0000-0000-0000-000000000002', 'gerer-silence-genant', $$Gérer un silence gênant$$, 2, ARRAY['conversation']::text[], false, 1, null, 'premium', $json${"hook":"Tu es en tête-à-tête, la conversation ralentit, puis s'arrête. Trois secondes passent. Ton cœur s'accélère, tu cherches désespérément une phrase, n'importe laquelle. Ce malaise a une explication précise : des chercheurs ont mesuré, au dixième de seconde près, à quel moment un silence commence à faire mal, et pourquoi.","diagnostic":{"kind":"slider","question":"À quel point un silence de quelques secondes dans une conversation te met-il mal à l'aise ?","min":1,"max":10,"minLabel":"Pas du tout","maxLabel":"Panique totale"},"cards":[{"title":"Le silence menace un besoin précis, pas ton ego","advice":"Un silence de quelques secondes entre inconnus active une inquiétude sociale spécifique, le besoin d'appartenance, pas un jugement réel sur toi. Le comprendre suffit souvent à baisser la panique.","sourceId":"a0000000-0000-0000-0000-000000000005"},{"title":"Le seuil, c'est environ 4 secondes","advice":"En dessous, un silence passe totalement inaperçu. Compter mentalement \"un, deux, trois\" avant de réagir t'évite de combler un vide qui, pour l'autre, n'existait pas encore.","sourceId":"a0000000-0000-0000-0000-000000000005"},{"title":"La relance par \"callback\"","advice":"Reviens sur un détail mentionné 2 minutes plus tôt (\"Tu disais tout à l'heure que...\") : c'est la relance la plus naturelle, elle ne sort pas de nulle part.","sourceId":"a0000000-0000-0000-0000-000000000002"},{"title":"Un silence n'est pas toujours à combler","advice":"Une fois la relation installée, le silence cesse d'être perçu négativement. Il peut même devenir un signe de confort mutuel : le stade de la relation explique cette gêne avec un inconnu, pas ta compétence sociale.","sourceId":"a0000000-0000-0000-0000-000000000006"},{"title":"Récap","advice":"Le silence menace un besoin précis (pas ta valeur), le seuil de gêne réel est plus court que tu crois compenser, le callback est ta relance la plus fiable.","sourceId":null}],"exercise":{"kind":"mcq-nuanced","prompt":"Un silence de 5 secondes vient de s'installer lors d'un café avec une connaissance récente. Laquelle de ces relances est la plus efficace ?","options":[{"text":"Revenir sur ce qu'elle a dit 5 minutes plus tôt et poser une question dessus","feedback":"C'est la plus efficace : elle relance un fil déjà engagé plutôt que d'ouvrir un sujet à froid ou de pointer le malaise, ce qui le renforcerait.","isBest":true},{"text":"Commenter la météo pour combler immédiatement","feedback":"Ouvrir un sujet totalement nouveau à froid est moins naturel qu'une relance sur un fil déjà engagé dans la conversation.","isBest":false},{"text":"S'excuser d'avoir \"fait un blanc\"","feedback":"Pointer le malaise à voix haute a tendance à le renforcer plutôt qu'à le désamorcer.","isBest":false}]},"personalization":{"condition":">=7","reorderCardIndexFirst":0}}$json$::jsonb),

('b0000000-0000-0000-0000-000000000003', 'sortir-conversation', $$Sortir poliment d'une conversation$$, 3, ARRAY['conversation']::text[], false, 1, null, 'premium', $json${"hook":"Ça fait dix minutes que tu cherches une porte de sortie polie, sans la trouver. Tu culpabilises à l'idée de \"vexer\" l'autre en partant. Une étude a suivi des milliers de conversations réelles pour répondre à une question simple : qui, vraiment, a envie que ça s'arrête ?","diagnostic":{"kind":"slider","question":"À quel point te sens-tu coupable quand tu veux mettre fin à une conversation ?","min":1,"max":10,"minLabel":"Pas du tout","maxLabel":"Énormément"},"cards":[{"title":"Tu n'es presque jamais seul à vouloir partir","advice":"Dans une étude sur des milliers de conversations, les deux personnes se sont mises d'accord sur le bon moment pour arrêter dans moins de 2% des cas. Et près d'une conversation sur trois s'arrête trop tard aux yeux d'au moins une des deux personnes.","sourceId":"a0000000-0000-0000-0000-000000000007"},{"title":"Personne ne suit ça d'aussi près que toi","advice":"Les chercheurs l'ont observé : chacun garde secrète son envie de partir. L'autre ne \"compte\" pas tes signaux de sortie, il ne les cherche probablement même pas.","sourceId":"a0000000-0000-0000-0000-000000000007"},{"title":"La sortie en 3 temps","advice":"Une observation (\"Il faut que j'y aille\"), une raison courte sans sur-justification, une phrase chaleureuse (\"Ravi d'avoir discuté !\"). Pas besoin de plus.","sourceId":"a0000000-0000-0000-0000-000000000008"},{"title":"Le mythe de la sortie parfaite","advice":"Il n'y a pas de moment \"juste\" universel. La recherche montre que ce moment n'existe même pas objectivement, chacun le perçoit différemment. Viser une sortie \"correcte\" plutôt que \"parfaite\" suffit.","sourceId":"a0000000-0000-0000-0000-000000000007"},{"title":"Récap","advice":"Statistiquement, l'autre a probablement aussi envie que ça se termine ; une sortie en 3 temps suffit ; il n'y a pas de \"bon moment\" objectif à chercher.","sourceId":null}],"exercise":{"kind":"predict-compare","prompt":"Tu es coincé dans une conversation depuis 15 minutes lors d'un afterwork, tu dois partir dans 5 minutes. Qu'est-ce que tu dirais pour sortir poliment ?","examples":["\"Il faut que j'y aille, j'ai un truc tôt demain. Ravi d'avoir discuté avec toi !\"","\"Je vais aller saluer d'autres personnes avant de partir, à bientôt !\"","\"Ça a été un plaisir de papoter, je file mais on se recroise vite.\""]}}$json$::jsonb),

('b0000000-0000-0000-0000-000000000004', 'recuperer-energie', $$Récupérer son énergie après un événement social$$, 4, ARRAY['recuperation', 'energie']::text[], false, 1, null, 'premium', $json${"hook":"L'événement est fini depuis une heure. Tu es rentré, la porte est fermée, et pourtant tu te sens vidé, presque groggy, incapable d'enchaîner sur autre chose. Cette fatigue n'a rien de mental : elle se mesure dans ton système nerveux, et une méthode précise existe pour la récupérer plus vite.","diagnostic":{"kind":"slider","question":"Sur une échelle de 1 à 10, à quel point te sens-tu épuisé socialement en ce moment ?","min":1,"max":10,"minLabel":"Pas du tout","maxLabel":"Complètement vidé"},"cards":[{"title":"Ton système nerveux, pas ton caractère","advice":"Les personnes introverties partent d'un niveau d'éveil cérébral déjà plus élevé au repos ; un événement social les fait donc franchir plus vite leur seuil optimal, ce qui déclenche la fatigue. C'est physiologique, pas un manque de volonté.","sourceId":"a0000000-0000-0000-0000-000000000009"},{"title":"La \"niche restauratrice\"","advice":"Après avoir agi \"hors de son tempérament naturel\" (sourire, faire la conversation, rester stimulé), le cerveau a besoin d'un espace qui correspond à sa nature de base pour récupérer : silence, stimulation réduite, seul.","sourceId":"a0000000-0000-0000-0000-000000000010"},{"title":"Négocie ta récupération à l'avance","advice":"Prévenir ton entourage (\"j'ai besoin d'une heure seul en rentrant\") avant même l'événement, plutôt que de te justifier après coup, réduit la culpabilité et protège vraiment ce temps.","sourceId":"a0000000-0000-0000-0000-000000000010"},{"title":"Recharge active, pas juste passive","advice":"Toute \"pause\" ne recharge pas de la même façon : une activité à faible stimulation sensorielle (silence, nature, lecture) recharge mieux qu'une activité qui continue de solliciter l'attention (réseaux sociaux, série captivante).","sourceId":"a0000000-0000-0000-0000-000000000009"},{"title":"Récap","advice":"La fatigue post-événement est physiologique, pas un défaut ; ta niche restauratrice doit être planifiée, pas improvisée ; toutes les pauses ne se valent pas.","sourceId":null}],"exercise":{"kind":"predict-compare","prompt":"Qu'est-ce que tu pourrais mettre en place dans les 2 heures après ton prochain événement social pour récupérer efficacement ?","examples":["Silence total et lumière tamisée pendant 30 minutes en rentrant, sans écran.","Une promenade seul, sans podcast ni musique, pour laisser l'esprit se vider.","Un moment de lecture plutôt qu'une série ou les réseaux sociaux."]}}$json$::jsonb),

('b0000000-0000-0000-0000-000000000005', 'gerer-anxiete-avant-evenement', $$Gérer l'anxiété avant un événement$$, 5, ARRAY['anxiete']::text[], false, 1, null, 'premium', $json${"hook":"L'événement est dans trois jours. Tu y penses déjà en boucle : et si je ne trouve rien à dire, et si c'est gênant, et si... L'anxiété que tu ressens là, maintenant, avant même que rien ne se soit passé, a un nom précis en psychologie clinique. C'est souvent elle, pas l'événement lui-même, qui fait le plus de dégâts.","diagnostic":{"kind":"slider-double","questions":["Sur 10, à quel point es-tu anxieux à l'idée de cet événement, là, maintenant ?","D'après toi, sur 10, à quel point l'événement se passera-t-il mal réellement ?"]},"cards":[{"title":"Le vrai coupable : la rumination \"avant\"","advice":"Le modèle de référence en thérapie cognitivo-comportementale de l'anxiété sociale identifie la rumination anticipatoire (repasser en boucle des scénarios négatifs avant l'événement) comme un moteur central qui entretient l'anxiété, indépendamment de ce qui se passe réellement.","sourceId":"a0000000-0000-0000-0000-000000000011"},{"title":"Repérer la pensée automatique","advice":"\"Je vais être gênant\", \"personne ne voudra me parler\" : ce sont des prédictions, pas des faits. Les nommer comme telles (\"c'est une pensée, pas une certitude\") réduit déjà leur emprise.","sourceId":"a0000000-0000-0000-0000-000000000011"},{"title":"Arrête de \"t'entraîner\" en boucle","advice":"Le même modèle identifie les comportements de sécurité (répéter mentalement ce que tu vas dire, éviter le regard, sur-préparer) comme des stratégies qui, paradoxalement, entretiennent l'anxiété au lieu de la réduire.","sourceId":"a0000000-0000-0000-0000-000000000011"},{"title":"Compare après coup","advice":"Note ta prédiction avant l'événement, puis reviens dessus après : l'écart entre ce que tu craignais et ce qui s'est vraiment passé est souvent l'argument le plus convaincant contre l'anxiété anticipatoire, plus que n'importe quel conseil.","sourceId":"a0000000-0000-0000-0000-000000000011"},{"title":"Récap","advice":"L'anxiété \"avant\" vient surtout de la rumination, pas de l'événement ; repère tes pensées automatiques ; arrête de sur-préparer ; compare prédiction et réalité après coup.","sourceId":null}],"exercise":{"kind":"guided-response","prompt":"Écris la pensée qui tourne en boucle avant cet événement.","followUp":"Maintenant, reformule-la comme une prédiction testable plutôt qu'un fait (\"Je prédis que... mais je ne le sais pas encore\")."}}$json$::jsonb),

('b0000000-0000-0000-0000-000000000006', 'repondre-blanc-mental', $$Répondre lors d'un blanc mental$$, 6, ARRAY['conversation']::text[], false, 1, null, 'premium', $json${"hook":"Quelqu'un vient de te poser une question. Et là, rien. Ta tête est vide, les secondes s'étirent, tu sens la panique monter. Bonne nouvelle : répondre \"à chaud\" sans texte préparé est une compétence spécifique, et elle s'entraîne avec des méthodes déjà testées.","diagnostic":{"kind":"slider","question":"À quel point la peur du blanc mental t'empêche-t-elle de te lancer dans une conversation ?","min":1,"max":10,"minLabel":"Pas du tout","maxLabel":"Ça me bloque complètement"},"cards":[{"title":"Vise \"assez bien\", pas \"parfait\"","advice":"Chercher la réponse idéale sature ta charge mentale et bloque encore plus. Viser une réponse \"suffisante\" libère de l'espace cognitif pour parler, tout simplement.","sourceId":"a0000000-0000-0000-0000-000000000012"},{"title":"L'improvisation, ça s'entraîne (et ça marche), avec preuves","advice":"Une expérience contrôlée a montré que des personnes formées à l'improvisation théâtrale, même sur une courte durée, développaient une meilleure tolérance à l'incertitude et un mieux-être affectif mesurable, comparées à un groupe témoin.","sourceId":"a0000000-0000-0000-0000-000000000013"},{"title":"Dis le blanc, ne le cache pas","advice":"Un principe central de l'improvisation : accepter ce qui arrive plutôt que lutter contre. Dire simplement \"attends, laisse-moi réfléchir une seconde\" est plus fluide, et plus humain, qu'un silence figé suivi de panique.","sourceId":"a0000000-0000-0000-0000-000000000013"},{"title":"Des phrases-pont à avoir en réserve","advice":"\"C'est une bonne question, laisse-moi y réfléchir\", \"ça me fait penser à...\", \"en fait je n'y avais pas pensé comme ça\" : mémoriser 2-3 phrases-pont te donne du temps sans silence gênant.","sourceId":"a0000000-0000-0000-0000-000000000012"},{"title":"Récap","advice":"Vise \"assez bien\" plutôt que parfait, entraîne-toi à l'incertitude comme une compétence, verbalise le blanc au lieu de le cacher, garde des phrases-pont en réserve.","sourceId":null}],"exercise":{"kind":"predict-compare","prompt":"On te demande \"Et toi, tu en penses quoi ?\" sur un sujet que tu ne maîtrises pas du tout. Ta tête est vide. Qu'est-ce que tu dirais ?","examples":["\"C'est une bonne question, laisse-moi y réfléchir une seconde.\"","\"Ça me fait penser à... en fait je n'y avais pas pensé comme ça avant.\"","\"Honnêtement je ne connais pas trop le sujet, qu'est-ce que toi tu en penses ?\""]}}$json$::jsonb),

('b0000000-0000-0000-0000-000000000007', 'repas-reunions-famille', $$Gérer les repas et réunions de famille$$, 7, ARRAY['famille', 'repas']::text[], false, 1, null, 'premium', $json${"hook":"Le repas commence à peine que ton oncle lance déjà une remarque sur ta vie que tu redoutais. Tu sens ta mâchoire se serrer. Ce qui va se passer dans les 3 prochaines minutes est, statistiquement, presque entièrement prévisible d'après des décennies de recherche sur la façon dont les tensions démarrent et dégénèrent, ou non.","diagnostic":{"kind":"slider","question":"À quel point redoutes-tu qu'un sujet précis revienne à la prochaine réunion de famille ?","min":1,"max":10,"minLabel":"Pas du tout","maxLabel":"J'y pense déjà en boucle"},"cards":[{"title":"Les 3 premières minutes comptent presque tout","advice":"Une recherche menée sur des décennies de discussions filmées montre que la façon dont un échange démarre prédit avec une précision très élevée comment il va se terminer. Si un sujet démarre déjà sur un ton accusateur, désamorce tout de suite plutôt que d'entrer dans le fond.","sourceId":"a0000000-0000-0000-0000-000000000014"},{"title":"La tentative de réparation","advice":"Les familles qui gèrent bien les tensions ne cherchent pas à éviter tout désaccord. Elles savent le désamorcer en cours de route, par une phrase, un geste, ou même une pointe d'humour, avant que ça escalade.","sourceId":"a0000000-0000-0000-0000-000000000014"},{"title":"Change de sujet sans confrontation directe","advice":"Une redirection neutre (\"Tiens, en parlant de ça, tu as vu que...\") détourne le fil sans déclarer ouvertement que tu refuses le sujet. C'est une technique de désescalade simple, éprouvée en pratique.","sourceId":"a0000000-0000-0000-0000-000000000015"},{"title":"Tu n'as pas à gagner le débat","advice":"Au repas de famille, le but est de préserver la relation, pas d'avoir raison. Lâcher le besoin de convaincre change complètement le niveau de tension.","sourceId":"a0000000-0000-0000-0000-000000000014"},{"title":"Récap","advice":"Désamorce dès les premières secondes, utilise une tentative de réparation avant l'escalade, redirige sans confronter, laisse tomber le besoin d'avoir raison.","sourceId":null}],"exercise":{"kind":"mcq-nuanced","prompt":"Ta tante fait une remarque désobligeante sur un de tes choix de vie à table. Laquelle de ces réponses est la plus efficace pour désamorcer sans envenimer ?","options":[{"text":"Répondre avec humour puis rediriger la conversation vers un autre sujet","feedback":"Désamorce sans escalade ni sacrifice de dignité : c'est une vraie tentative de réparation.","isBest":true},{"text":"Expliquer en détail et avec passion pourquoi elle a tort","feedback":"Alimente le conflit dès les premières secondes plutôt que de le désamorcer.","isBest":false},{"text":"Ignorer complètement et changer de visage","feedback":"Peut être perçu comme un signal de tension non résolu plutôt qu'une vraie désescalade.","isBest":false}]}}$json$::jsonb),

('b0000000-0000-0000-0000-000000000008', 'amis-age-adulte', $$Se faire des amis à l'âge adulte$$, 8, ARRAY['amitie']::text[], false, 1, null, 'premium', $json${"hook":"Tu regardes tes contacts : des collègues, des connaissances, personne à qui envoyer un message \"juste pour parler\". Se faire des amis à l'âge adulte semble impossible. Pourtant, une étude a mesuré précisément ce qu'il faut, en heures, pour transformer un inconnu en ami. La réponse est rassurante : le temps cumulé compte plus que la chance.","diagnostic":{"kind":"slider","question":"À quel point te sens-tu seul socialement en ce moment ?","min":1,"max":10,"minLabel":"Pas du tout","maxLabel":"Énormément"},"cards":[{"title":"Ce n'est pas toi, c'est le manque d'heures","advice":"Il faut environ 40 à 60 heures passées ensemble pour devenir des amis \"occasionnels\", 80 à 100 heures pour devenir vraiment amis, et plus de 200 heures pour un ami proche. L'amitié à l'âge adulte n'a rien de magique : elle s'accumule.","sourceId":"a0000000-0000-0000-0000-000000000016"},{"title":"La répétition compte plus que la profondeur, au début","advice":"Dans les premières heures, ce sont les interactions répétées, même courtes et légères, qui font avancer la relation, pas une seule conversation \"profonde\".","sourceId":"a0000000-0000-0000-0000-000000000016"},{"title":"Le travail ne compte presque pas","advice":"Les heures passées à travailler ensemble comptent beaucoup moins que les heures de loisirs partagés ou de simples moments informels. Un collègue avec qui tu ris à la pause compte plus, pour l'amitié, qu'un projet commun.","sourceId":"a0000000-0000-0000-0000-000000000016"},{"title":"Vise la récurrence, pas l'événement unique","advice":"Rejoindre une activité hebdomadaire ou mensuelle (club, sport, cours) accumule les heures nécessaires bien plus vite qu'une série de rencontres isolées, même nombreuses.","sourceId":"a0000000-0000-0000-0000-000000000016"},{"title":"Récap","advice":"L'amitié adulte est une question d'heures cumulées, pas de chance ; privilégie la récurrence à l'événement unique ; le contexte informel compte plus que le contexte professionnel.","sourceId":null}],"exercise":{"kind":"free-plan","prompt":"Identifie une activité récurrente (hebdomadaire ou mensuelle) que tu pourrais rejoindre pour accumuler du temps avec les mêmes personnes.","examples":["Un cours collectif (sport, langue, art) qui revient chaque semaine.","Un club ou une association liée à un centre d'intérêt existant.","Un groupe de jeu ou une activité régulière avec des collègues ou connaissances."]}}$json$::jsonb),

('b0000000-0000-0000-0000-000000000009', 'small-talk-travail', $$Gérer les petites conversations au travail (small talk)$$, 9, ARRAY['travail']::text[], false, 1, null, 'premium', $json${"hook":"La machine à café. Encore. Tu sens déjà venir la question \"ça va, ce week-end ?\" et l'échange creux qui suivra. Le small talk te semble être une perte de temps et d'énergie. Pourtant, une étude menée sur des centaines d'employés a mesuré ce qu'il t'apporte vraiment, au-delà de l'apparence.","diagnostic":{"kind":"slider","question":"À quel point le small talk au travail te semble-t-il une perte de temps et d'énergie ?","min":1,"max":10,"minLabel":"Pas du tout","maxLabel":"Complètement"},"cards":[{"title":"Le small talk n'est pas superficiel, il finance ta journée","advice":"Une étude menée auprès de plus de 150 employés a montré que le small talk quotidien augmente les émotions positives et le sentiment de bien-être en fin de journée, et rend plus enclin à aider ses collègues.","sourceId":"a0000000-0000-0000-0000-000000000017"},{"title":"Mais il a un vrai coût cognitif","advice":"La même étude montre un effet double, \"stimulant mais distrayant\" : le small talk peut couper ta concentration. La solution n'est pas de l'éviter, mais de le cadrer dans le temps (2-3 minutes suffisent).","sourceId":"a0000000-0000-0000-0000-000000000017"},{"title":"C'est un rituel, pas un test","advice":"Le fait même de l'échange compte plus que la profondeur ou l'originalité du contenu, comme un rituel social. Ça enlève la pression d'être \"intéressant\".","sourceId":"a0000000-0000-0000-0000-000000000017"},{"title":"FORD, version bureau","advice":"Reprends la méthode FORD du cours 1, mais évite \"Famille\" (trop personnel en contexte pro) et privilégie Occupation et loisirs neutres : \"Tu avances sur quoi en ce moment ?\", \"Tu as vu un bon film récemment ?\".","sourceId":"a0000000-0000-0000-0000-000000000002"},{"title":"Récap","advice":"Le small talk améliore réellement ton bien-être au travail, cadre-le dans le temps pour limiter son coût cognitif, et traite-le comme un rituel plutôt qu'un test de personnalité.","sourceId":null}],"exercise":{"kind":"predict-compare","prompt":"Tu croises un collègue à la machine à café. Qu'est-ce que tu dirais pour lancer une conversation courte et naturelle ?","examples":["\"Tu avances sur quoi en ce moment ?\"","\"Tu as vu un bon film ou une série récemment ?\"","\"Cette machine à café est capricieuse aujourd'hui, hein ?\" (commentaire de contexte)"]}}$json$::jsonb),

('b0000000-0000-0000-0000-000000000010', 'poser-limite-sociale', $$Poser une limite sociale sans culpabiliser$$, 10, ARRAY['limites']::text[], false, 1, null, 'premium', $json${"hook":"Tu viens de dire \"oui\" à une sollicitation dont tu n'avais pas envie. Encore une fois. La boule au ventre s'installe déjà. Poser une limite semble impossible sans se sentir égoïste, pourtant une synthèse de plusieurs essais contrôlés montre que cette capacité s'entraîne, avec un effet mesurable.","diagnostic":{"kind":"slider","question":"À quel point te sens-tu coupable quand tu dis non à une sollicitation sociale ?","min":1,"max":10,"minLabel":"Pas du tout","maxLabel":"Énormément"},"cards":[{"title":"Ça s'entraîne, avec des preuves","advice":"Une synthèse de 12 essais contrôlés randomisés portant sur plus de 500 personnes a montré que l'entraînement à l'affirmation de soi produit un effet réel et mesurable sur le comportement assertif et l'anxiété sociale.","sourceId":"a0000000-0000-0000-0000-000000000018"},{"title":"La formule DESC","advice":"Décris les faits, Exprime ce que tu ressens, Spécifie ce que tu proposes, précise les Conséquences positives. Une structure simple pour poser une limite sans agressivité ni justification excessive.","sourceId":"a0000000-0000-0000-0000-000000000019"},{"title":"Dire non sans se justifier pendant 5 minutes","advice":"Une phrase courte suffit : \"Je ne suis pas disponible ce soir-là.\" Sur-expliquer donne à l'autre plus de prise pour négocier ta limite.","sourceId":"a0000000-0000-0000-0000-000000000020"},{"title":"La culpabilité n'est pas un signal d'erreur","advice":"La gêne initiale après avoir posé une limite est normale, et elle diminue avec la pratique, comme le montre l'effet d'entraînement de la méta-analyse. Ce n'est pas un signe que tu as mal agi.","sourceId":"a0000000-0000-0000-0000-000000000018"},{"title":"Récap","advice":"Poser des limites est une compétence entraînable et prouvée ; utilise DESC ; une phrase courte suffit ; la culpabilité initiale est normale et passagère.","sourceId":null}],"exercise":{"kind":"predict-compare","prompt":"On te sollicite pour quelque chose dont tu n'as pas envie. Écris ta réponse en utilisant la structure DESC.","examples":["\"Ce week-end je suis déjà pris (D). Ça me tient à cœur de pouvoir souffler un peu (E). Est-ce qu'on peut se voir la semaine d'après à la place (S) ? On profitera d'avoir plus de temps (C).\"","\"Je ne suis pas disponible ce soir-là (D). Je préfère être honnête plutôt que d'annuler après (E). Je te propose une autre date (S), comme ça on est sûrs d'en profiter vraiment (C).\""]}}$json$::jsonb),

('b0000000-0000-0000-0000-000000000011', 'rejoindre-groupe', $$Rejoindre un groupe déjà en pleine conversation$$, 11, ARRAY['groupe', 'conversation']::text[], false, 1, null, 'premium', $json${"hook":"Tu arrives à une soirée. Un petit groupe discute déjà en cercle, animé, personne ne te voit. Tu restes planté à côté, sans savoir comment t'insérer sans avoir l'air d'interrompre. Ce moment précis a été étudié en détail par les chercheurs qui analysent comment les groupes s'organisent physiquement dans l'espace pendant une conversation.","diagnostic":{"kind":"slider","question":"À quel point te sens-tu à l'aise pour rejoindre un groupe déjà en pleine conversation ?","min":1,"max":10,"minLabel":"Terrifié","maxLabel":"Aucun souci"},"cards":[{"title":"Le cercle \"ouvert\" est une vraie invitation","advice":"Les groupes en conversation forment naturellement des arrangements spatiaux étudiés en sciences sociales : un cercle légèrement ouvert (pas complètement fermé) est une configuration reconnue comme une invitation implicite à s'approcher. Ce n'est pas un hasard si certains groupes te \"laissent de la place\" et d'autres non.","sourceId":"a0000000-0000-0000-0000-000000000025"},{"title":"Positionne-toi avant de parler","advice":"Approche-toi de l'ouverture du cercle, établis un contact visuel bref, hoche légèrement la tête. Laisse le groupe t'intégrer visuellement avant de dire quoi que ce soit : le positionnement précède la prise de parole.","sourceId":"a0000000-0000-0000-0000-000000000025"},{"title":"Écoute 10 secondes avant d'intervenir","advice":"Capter le sujet en cours évite l'entrée \"à l'aveugle\" qui casse la dynamique. Une fois le sujet identifié, ton entrée paraît naturelle plutôt que plaquée.","sourceId":"a0000000-0000-0000-0000-000000000026"},{"title":"Entre avec une question, pas une déclaration","advice":"Une question ouverte liée à ce qui vient d'être dit (\"Attends, comment vous en êtes arrivés là ?\") s'intègre plus naturellement qu'une remarque sans lien, et donne immédiatement la parole à quelqu'un du groupe.","sourceId":"a0000000-0000-0000-0000-000000000003"},{"title":"Récap","advice":"Repère un cercle ouvert plutôt que fermé, positionne-toi avant de parler, écoute quelques secondes pour capter le sujet, entre avec une question plutôt qu'une déclaration.","sourceId":null}],"exercise":{"kind":"mcq-nuanced","prompt":"Tu repères un groupe de 4 personnes en cercle légèrement ouvert lors d'un événement. Laquelle de ces approches est la plus efficace ?","options":[{"text":"S'approcher de l'ouverture, écouter quelques secondes, puis poser une question liée au sujet en cours","feedback":"Respecte à la fois le positionnement spatial et le fil de la conversation.","isBest":true},{"text":"S'approcher et se présenter directement à tout le groupe avant qu'ils aient fini leur phrase","feedback":"Casse la dynamique en cours.","isBest":false},{"text":"Attendre un silence total du groupe avant d'oser s'approcher","feedback":"Risque de ne jamais arriver, un silence total étant rare dans un groupe animé.","isBest":false}]}}$json$::jsonb),

('b0000000-0000-0000-0000-000000000012', 'ecouter-vraiment', $$Écouter pour de vrai$$, 12, ARRAY['ecoute']::text[], false, 1, null, 'premium', $json${"hook":"Un ami te raconte sa journée. Tu hoches la tête, mais une partie de toi est déjà en train de préparer ce que tu vas répondre. Tu n'écoutes qu'à moitié, et lui le sent probablement aussi. Plusieurs études en laboratoire ont mesuré ce qui change, chez la personne qui parle, quand elle se sent vraiment écoutée.","diagnostic":{"kind":"slider","question":"À quel point penses-tu déjà à ta réponse pendant que l'autre parle ?","min":1,"max":10,"minLabel":"Jamais","maxLabel":"Presque toujours"},"cards":[{"title":"Écouter change l'autre, pas juste toi","advice":"Une écoute de haute qualité (empathique, attentive, non jugeante) réduit mesurablement l'anxiété sociale et la défensivité de la personne qui parle, à travers plusieurs expériences contrôlées en laboratoire.","sourceId":"a0000000-0000-0000-0000-000000000027"},{"title":"Les 3 ingrédients d'une bonne écoute","advice":"Les chercheurs identifient trois composantes déterminantes : l'empathie, l'attention réelle, et l'absence de jugement. Retirer un seul des trois suffit à réduire l'effet.","sourceId":"a0000000-0000-0000-0000-000000000027"},{"title":"Ça te rend aussi plus appréciable, toi","advice":"Les personnes qui se sentent bien écoutées rapportent un sentiment de connexion plus fort envers leur interlocuteur. Bien écouter te profite aussi, ce n'est pas qu'un sacrifice social.","sourceId":"a0000000-0000-0000-0000-000000000027"},{"title":"La technique du reflet","advice":"Avant de répondre ou de donner ton avis, reformule brièvement ce que tu viens d'entendre (\"si je comprends bien, tu es surtout frustré par...\") : ça force une écoute réelle et montre à l'autre qu'il a été entendu.","sourceId":"a0000000-0000-0000-0000-000000000028"},{"title":"Récap","advice":"Une écoute de qualité réduit l'anxiété de celui qui parle, repose sur 3 ingrédients précis (empathie, attention, non-jugement), et te rend toi-même plus appréciable.","sourceId":null}],"exercise":{"kind":"predict-compare","prompt":"Un ami te partage un problème. Qu'est-ce que tu dirais juste après qu'il ait fini de parler ?","examples":["\"Si je comprends bien, ce qui te pèse le plus c'est... c'est ça ?\"","\"Ça a l'air vraiment difficile à vivre, merci de me le partager.\"","\"Attends, donc concrètement, ce qui t'embête c'est plutôt X ou Y ?\""]}}$json$::jsonb),

('b0000000-0000-0000-0000-000000000013', 'rejet-social', $$Le rejet social, ça fait vraiment mal$$, 13, ARRAY['rejet']::text[], false, 1, null, 'premium', $json${"hook":"On t'a ignoré dans une conversation de groupe, ou pire, exclu d'un truc auquel tout le monde a été invité sauf toi. La blessure te semble disproportionnée par rapport à \"juste\" un rejet social, comme si tu réagissais trop fort. Une étude en imagerie cérébrale a montré que ta réaction n'a rien d'exagéré : ton cerveau traite littéralement ça comme une douleur physique.","diagnostic":{"kind":"slider","question":"À quel point la peur d'être ignoré ou rejeté t'empêche-t-elle d'aller vers les autres ?","min":1,"max":10,"minLabel":"Pas du tout","maxLabel":"Ça me bloque complètement"},"cards":[{"title":"Ton cerveau ne fait pas la différence","advice":"Une étude en IRMf a montré que l'exclusion sociale active le cortex cingulaire antérieur, la même zone cérébrale impliquée dans la douleur physique, et que cette activation est corrélée à la détresse ressentie.","sourceId":"a0000000-0000-0000-0000-000000000029"},{"title":"Donc ta réaction n'est pas \"exagérée\"","advice":"Cette douleur est neurologiquement réelle : ressentir une réaction forte face au rejet est le fonctionnement normal d'un cerveau humain, pas un signe d'hypersensibilité. Ça enlève une couche de honte inutile ajoutée à la douleur initiale.","sourceId":"a0000000-0000-0000-0000-000000000029"},{"title":"La douleur sociale est un signal, pas une sentence","advice":"Les chercheurs décrivent cette douleur comme une alarme : elle signale une rupture de lien à réparer, pas une preuve que tu ne mérites pas d'appartenir quelque part.","sourceId":"a0000000-0000-0000-0000-000000000029"},{"title":"Reprends contact plutôt que d'éviter","advice":"Éviter systématiquement toute situation où un nouveau rejet pourrait survenir entretient la douleur sur le long terme ; un petit pas de reconnexion, même minime, est plus protecteur que l'évitement complet.","sourceId":"a0000000-0000-0000-0000-000000000030"},{"title":"Récap","advice":"Le rejet active un vrai circuit de douleur cérébrale ; ta réaction n'est pas exagérée ; c'est un signal à traiter, pas une sentence ; reconnecte-toi plutôt que d'éviter.","sourceId":null}],"exercise":{"kind":"guided-response","prompt":"Repense à un moment récent où tu t'es senti ignoré ou exclu. Écris la phrase que tu t'es dite sur toi-même à ce moment-là.","followUp":"Réécris-la en tenant compte du fait que c'est une douleur réelle, pas une preuve que tu as fait quelque chose de mal."}}$json$::jsonb),

('b0000000-0000-0000-0000-000000000014', 'reseauter-sans-se-forcer', $$Réseauter sans se forcer$$, 14, ARRAY['travail', 'reseau']::text[], false, 1, null, 'premium', $json${"hook":"Un événement professionnel dans deux jours. Rien que d'y penser, tu sens déjà la fatigue : sourire poliment, faire semblant que tout ça sert à quelque chose, échanger des cartes de visite avec des gens que tu ne reverras jamais. Sauf qu'une étude fondatrice en sociologie, restée l'une des plus citées de son domaine, montre exactement le contraire : ce sont ces liens légers qui comptent le plus.","diagnostic":{"kind":"slider","question":"À quel point le réseautage professionnel te semble-t-il artificiel ou inutile ?","min":1,"max":10,"minLabel":"Pas du tout","maxLabel":"Complètement"},"cards":[{"title":"Ce sont les liens faibles qui ouvrent des portes","advice":"Une étude devenue une référence en sociologie a interrogé des centaines de personnes sur la façon dont elles avaient trouvé leur emploi : leurs connaissances éloignées et occasionnelles se sont révélées statistiquement plus utiles que leurs proches pour accéder à de nouvelles opportunités.","sourceId":"a0000000-0000-0000-0000-000000000031"},{"title":"Pourquoi ça marche : l'info ne se répète pas","advice":"Tes proches connaissent déjà ce que tu sais. Tes connaissances éloignées, elles, évoluent dans des cercles différents, et t'apportent des informations que ton entourage proche ne peut pas te donner.","sourceId":"a0000000-0000-0000-0000-000000000031"},{"title":"Vise 1 lien, pas 20","advice":"Puisque la valeur vient des liens légers eux-mêmes, pas de leur nombre ni de leur intensité, l'objectif réaliste d'un événement n'est pas \"réseauter avec tout le monde\" mais repartir avec une seule connexion légère mais réelle.","sourceId":"a0000000-0000-0000-0000-000000000031"},{"title":"Le suivi compte plus que la soirée","advice":"Un lien faible se maintient avec un minimum de contact périodique (un message tous les quelques mois suffit). Pas besoin d'intensité ni de fréquence pour qu'il reste utile.","sourceId":"a0000000-0000-0000-0000-000000000032"},{"title":"Récap","advice":"Les liens faibles sont statistiquement plus utiles que les liens forts pour les opportunités ; vise une seule connexion réelle par événement plutôt que la quantité ; entretiens-la avec un contact minimal mais régulier.","sourceId":null}],"exercise":{"kind":"free-plan","prompt":"Choisis une personne rencontrée récemment lors d'un événement pro. Quel message court pourrais-tu lui envoyer cette semaine pour garder le contact ?","examples":["\"Ravi d'avoir échangé l'autre jour, je repense à ce que tu disais sur [sujet], ça m'a donné à réfléchir !\"","\"Petit message pour garder le contact après notre échange à [événement], n'hésite pas si je peux t'être utile un jour.\""]}}$json$::jsonb),

('b0000000-0000-0000-0000-000000000015', 'compliment-sincere', $$Faire un compliment sincère sans que ce soit bizarre$$, 15, ARRAY['compliment']::text[], false, 1, null, 'premium', $json${"hook":"Tu penses un vrai compliment à quelqu'un : sa façon de présenter les choses, un choix qu'il a fait, un détail que tu apprécies chez lui. Et tu le gardes pour toi, en imaginant que ça sonnerait faux ou gênant. Neuf expériences menées sur ce réflexe montrent que tu te trompes, et toujours dans le même sens.","diagnostic":{"kind":"slider","question":"À quel point retiens-tu des compliments sincères par peur que ce soit gênant ?","min":1,"max":10,"minLabel":"Jamais","maxLabel":"Presque toujours"},"cards":[{"title":"Tu sous-estimes l'effet, dans les deux sens","advice":"Sur neuf expériences, les personnes qui faisaient un compliment sous-estimaient systématiquement à quel point il rendrait l'autre heureux, tout en surestimant à quel point ce serait gênant. Les deux erreurs vont dans le même sens : celui qui te retient d'agir.","sourceId":"a0000000-0000-0000-0000-000000000033"},{"title":"Ça ne s'use pas","advice":"Contrairement à l'intuition, répéter des compliments sincères à la même personne ne les rend pas moins sincères ni moins appréciés à ses yeux, l'effet ne s'épuise pas avec la répétition.","sourceId":"a0000000-0000-0000-0000-000000000033"},{"title":"Sois précis, pas générique","advice":"Un compliment spécifique (\"ta façon d'expliquer ce point était hyper claire\") est perçu comme plus sincère et a plus d'impact qu'un compliment vague (\"t'es sympa\").","sourceId":"a0000000-0000-0000-0000-000000000033"},{"title":"Dis-le sur le moment","advice":"Plus tu attends, plus l'occasion se referme et plus ton hésitation grandit : le compliment dit dans l'instant demande moins de courage que celui préparé après coup.","sourceId":"a0000000-0000-0000-0000-000000000034"},{"title":"Récap","advice":"Tu sous-estimes l'impact positif d'un compliment et surestimes sa gêne ; il ne s'use pas avec la répétition ; sois précis plutôt que vague ; dis-le sur le moment.","sourceId":null}],"exercise":{"kind":"predict-compare","prompt":"Pense à quelqu'un que tu vois régulièrement. Écris un compliment précis et sincère que tu pourrais lui faire cette semaine.","examples":["\"Ta façon d'expliquer ce dossier était hyper claire, j'ai tout de suite compris.\"","\"J'ai trouvé ta remarque en réunion hier super pertinente, ça a changé ma façon de voir le problème.\""]}}$json$::jsonb),

('b0000000-0000-0000-0000-000000000016', 'faire-monter-conversation', $$Faire monter une conversation$$, 16, ARRAY['conversation']::text[], false, 2, 'b0000000-0000-0000-0000-000000000001', 'premium', $json${"hook":"La conversation dure depuis dix minutes. Météo, boulot, week-end. Tu sens qu'elle pourrait aller plus loin, mais une question un peu plus personnelle te semble risquée, comme si tu allais mettre l'autre mal à l'aise. Une étude sur plus de 1800 personnes a testé cette peur, en confrontant des inconnus à des questions bien plus profondes que la météo.","diagnostic":{"kind":"slider","question":"À quel point as-tu peur qu'une question plus personnelle mette l'autre mal à l'aise ?","min":1,"max":10,"minLabel":"Pas du tout","maxLabel":"Énormément"},"cards":[{"title":"Ton estimation est fausse, dans le bon sens","advice":"Dans 12 expériences menées sur plus de 1800 participants, les conversations profondes entre inconnus se sont systématiquement révélées moins gênantes, plus connectantes et plus agréables que ce que les deux parties avaient prédit avant de commencer.","sourceId":"a0000000-0000-0000-0000-000000000021"},{"title":"Monte d'un cran, pas de dix","advice":"Pas besoin de sauter directement à une question intime, une question légèrement plus personnelle que la moyenne (\"Qu'est-ce qui te motive dans ce que tu fais ?\" plutôt que \"Tu bosses où ?\") suffit à faire basculer une conversation vers plus de connexion.","sourceId":"a0000000-0000-0000-0000-000000000021"},{"title":"Partage à la même profondeur","advice":"Dans l'étude, les échanges les plus connectants étaient réciproques : après avoir posé une question plus personnelle, partage aussi quelque chose d'un niveau de profondeur comparable sur toi-même.","sourceId":"a0000000-0000-0000-0000-000000000021"},{"title":"Récap","advice":"Tu surestimes largement la gêne que provoque une question plus personnelle ; monte d'un cran progressivement ; partage à la même profondeur que ce que tu demandes.","sourceId":null}],"exercise":{"kind":"predict-compare","prompt":"Pense à une personne que tu connais un peu (collègue, connaissance) avec qui tu aimerais approfondir la conversation. Quelle question, légèrement plus personnelle que d'habitude, pourrais-tu lui poser ?","examples":["\"Qu'est-ce qui te motive vraiment dans ce que tu fais ?\"","\"C'est quoi un truc dont tu es vraiment fier ces derniers temps ?\""]}}$json$::jsonb),

('b0000000-0000-0000-0000-000000000017', 'arreter-ruminations', $$Après l'événement : arrêter les ruminations$$, 17, ARRAY['anxiete', 'recuperation']::text[], false, 2, 'b0000000-0000-0000-0000-000000000005', 'premium', $json${"hook":"L'événement est terminé depuis des heures, mais toi, tu es encore dedans : tu repasses en boucle cette phrase que tu as mal formulée, ce silence bizarre, ce regard que tu as peut-être mal interprété. Ce phénomène a un nom précis en recherche clinique, et il a été mesuré : plus tu rumines, plus ton souvenir de l'événement se déforme dans le sens négatif.","diagnostic":{"kind":"slider","question":"Après un événement social, à quel point repasses-tu mentalement ce qui s'est dit ou ce que tu aurais dû dire ?","min":1,"max":10,"minLabel":"Pas du tout","maxLabel":"En boucle pendant des heures"},"cards":[{"title":"Ça s'appelle le \"post-event processing\"","advice":"C'est un phénomène mesuré et corrélé à l'anxiété sociale : des souvenirs récurrents et intrusifs de l'événement, qui interfèrent avec la concentration et poussent à éviter des situations similaires.","sourceId":"a0000000-0000-0000-0000-000000000022"},{"title":"Le souvenir se déforme pendant que tu rumines","advice":"Ce n'est pas un rejeu neutre : plus tu repasses l'événement, plus ton souvenir se biaise vers les détails négatifs, même si l'événement s'est objectivement bien passé. La rumination fabrique le souvenir qu'elle prétend analyser.","sourceId":"a0000000-0000-0000-0000-000000000022"},{"title":"Fixe une fenêtre, pas un accès illimité","advice":"Autorise-toi 10 minutes, à un moment précis de la journée, pour repenser à l'événement, puis stoppe consciemment en dehors de cette fenêtre. Contenir la rumination dans un créneau limité réduit son emprise sur le reste de la journée.","sourceId":"a0000000-0000-0000-0000-000000000023"},{"title":"Sépare les faits de l'histoire que tu te racontes","advice":"\"J'ai dit un truc bizarre\" est une interprétation, pas un fait. Écris ce qui s'est objectivement passé, puis à côté ce que tu en déduis sur toi. Les deux colonnes sont rarement aussi liées que ta rumination le laisse penser.","sourceId":"a0000000-0000-0000-0000-000000000011"},{"title":"Récap","advice":"Le post-event processing est un phénomène identifié et mesurable ; la rumination déforme le souvenir plus qu'elle ne l'analyse ; limite-la à une fenêtre de temps ; sépare les faits des interprétations.","sourceId":null}],"exercise":{"kind":"guided-response","prompt":"Pense à un événement social récent qui te trotte encore en tête. Colonne 1 : ce qui s'est objectivement passé, factuellement.","followUp":"Colonne 2 : ce que tu en déduis sur toi."}}$json$::jsonb),

('b0000000-0000-0000-0000-000000000018', 'entretenir-amitie', $$Entretenir une amitié dans la durée$$, 18, ARRAY['amitie']::text[], false, 2, 'b0000000-0000-0000-0000-000000000008', 'premium', $json${"hook":"Tu as mis des dizaines d'heures à devenir vraiment proche de quelqu'un. Et puis la vie prend le dessus, les semaines passent sans nouvelles, et le lien s'effiloche sans qu'aucune dispute n'ait eu lieu. Une étude longitudinale sur 18 mois a suivi ce phénomène. Bonne nouvelle : il obéit à des règles précises, pas au hasard.","diagnostic":{"kind":"slider","question":"Combien de tes amis proches as-tu contactés ce mois-ci ?","min":0,"max":10,"minLabel":"Aucun","maxLabel":"Tous"},"cards":[{"title":"L'amitié se dégrade sans contact, contrairement à la famille","advice":"Une étude longitudinale sur 18 mois montre que les liens familiaux résistent au manque de contact, mais que les amitiés, elles, se dégradent mesurablement sans entretien actif régulier.","sourceId":"a0000000-0000-0000-0000-000000000024"},{"title":"Le rythme dépend de la proximité du cercle","advice":"Plus une amitié est proche, plus elle demande de fréquence : contact quasi quotidien pour le cercle le plus intime, hebdomadaire pour les amis proches, mensuel pour les cercles plus larges.","sourceId":"a0000000-0000-0000-0000-000000000024"},{"title":"Pas le même levier pour tout le monde","advice":"La même étude observe une différence : le déclin est surtout évité par la fréquence des échanges (se parler) pour certains liens, et par les activités partagées pour d'autres. Identifie ce qui fonctionne le mieux avec chaque ami plutôt que d'appliquer la même recette à tous.","sourceId":"a0000000-0000-0000-0000-000000000024"},{"title":"Programme-le, ne le laisse pas au hasard","advice":"Puisque la dégradation est passive (elle arrive sans qu'il y ait de conflit), la seule protection efficace est active : planifier le contact à l'avance plutôt que de compter sur l'envie spontanée.","sourceId":"a0000000-0000-0000-0000-000000000024"},{"title":"Récap","advice":"Une amitié demande un entretien actif, contrairement à la famille ; adapte la fréquence à la proximité du lien ; identifie si c'est la conversation ou l'activité partagée qui compte le plus pour chaque ami ; planifie plutôt que d'attendre l'envie.","sourceId":null}],"exercise":{"kind":"free-plan","prompt":"Liste 3 amis proches. Pour chacun, quand les as-tu contactés pour la dernière fois ?","examples":["Programme un appel hebdomadaire avec ton ami le plus proche, même court.","Envoie un message simple à quelqu'un que tu n'as pas contacté depuis plus d'un mois : \"Je pensais à toi, comment tu vas ?\""]}}$json$::jsonb)
on conflict (id) do update set slug = excluded.slug, title = excluded.title, order_index = excluded.order_index, tags = excluded.tags, free_tier_included = excluded.free_tier_included, level = excluded.level, parent_course_id = excluded.parent_course_id, required_tier = excluded.required_tier, content = excluded.content;
